class IndependentNodeDefinitionTests(unittest.TestCase):
    def test_frozen_node_bytes_digests_and_rejections(self):
        self.assertEqual(len(VECTORS), 19)
        for vector in VECTORS:
            with self.subTest(vector=vector["id"]):
                value = strict_json.loads(vector["inputJson"], max_depth=128)
                if vector["accepted"]:
                    self.assertEqual(definition_bytes(value), vector["canonicalJson"].encode("utf-8"))
                    self.assertEqual(definition_digest(value), vector["digest"])
                else:
                    with self.assertRaises(Error):
                        definition_digest(value)
